// Package ansi encodes and parses the escape sequences a terminal
// understands.
//
// Sequences are values, not writes. Every constant and function here yields
// the exact bytes as a string, which the caller sends wherever it likes:
//
//	io.WriteString(w, ansi.CUP(0, 0))
//	buf.WriteString(ansi.EraseLineRight)
//
// Functions that take a count or a position return the shortest form the
// terminal accepts, because the renderer emits these on every frame and the
// difference shows up on the wire. [CUU] of 1 is "\x1b[A" rather than
// "\x1b[1A", and a movement of zero returns the empty string.
//
// Coordinates are zero-based throughout, and converted to the one-based wire
// form on the way out.
//
// There is no terminfo lookup. What a terminal supports is discovered by
// asking it, using the request sequences in this package and decoding the
// replies.
//
// Every sequence also has a Write counterpart in write.go, generated by
// genwrite, for callers working against an io.Writer.
//
//go:generate go run gen_write.go
package ansi

import "altscreen.io/vision/unicode/graphemeaw"

// WidthMethod selects how the display width of a grapheme cluster is
// measured. It does not affect where clusters break.
type WidthMethod uint8

const (
	// WcWidth sums the code-point widths of each cluster, as in wcswidth(3).
	// Combining marks, variation selectors, and joiners add no columns.
	// Other code points add their own widths, so a joined family emoji can
	// occupy eight columns.
	//
	// This is the zero value.
	WcWidth WidthMethod = iota

	// GraphemeWidth measures the whole cluster, accounting for variation
	// selectors, regional indicators, zero-width joiner sequences, and
	// pictographic presentation.
	GraphemeWidth
)

// StringWidth returns the number of terminal cells s occupies under m.
//
// East Asian Ambiguous code points count as one cell. Use
// [WidthMethod.StringWidthOptions] to count them as two.
func (m WidthMethod) StringWidth(s string) int {
	return m.StringWidthOptions(s, graphemeaw.Options{})
}

// StringWidthOptions returns the number of terminal cells s occupies under m,
// measuring with opts.
func (m WidthMethod) StringWidthOptions(s string, opts graphemeaw.Options) int {
	total := 0
	seg := opts.NewSegmenter([]byte(s))
	if m == GraphemeWidth {
		for seg.Next() {
			total += seg.Width()
		}
		return total
	}
	for seg.Next() {
		total += seg.WcWidth()
	}
	return total
}
